window.ELECTROBAZA_CATALOG = {"currentTopic":null,"groups":[{"id":"1me-25","name":"1МЭ-25","mark":"МЭ","disciplines":["mdk-05-01","mdk-05-02"]},{"id":"1eo-25","name":"1ЭО-25","mark":"ЭО","disciplines":["mdk-04-01","mdk-04-02-1eo-25-s1"]},{"id":"1eo-24","name":"1ЭО-24","mark":"ЭО","disciplines":["mdk-04-02-1eo-24-s3","op-08","op-12"]},{"id":"1a-25-3a-26-11","name":"1А-25 и 3А-26/11","mark":"А","disciplines":["op-03"]}],"disciplines":[{"id":"mdk-05-01","name":"МДК 05.01 Основы слесарно-сборочных и электромонтажных работ","contentPath":"groups/1me-25/mdk-05-01","topics":[]},{"id":"mdk-05-02","name":"МДК 05.02 Организация и выполнение работ по сборке и монтажу электрооборудования и распределительных устройств","contentPath":"groups/1me-25/mdk-05-02","topics":[{"id":"switch-socket-connection","name":"Подключение выключателей и розеток","materials":["switch-socket-connection-practice"]},{"id":"lighting-network-check","name":"Проверка осветительной сети","materials":["lighting-network-check-practice"]}]},{"id":"mdk-04-02-1eo-25-s1","name":"МДК 04.02 Организация работ по сборке, монтажу и ремонту электрооборудования","semester":1,"contentPath":"groups/1eo-25/mdk-04-02/semester-1","topics":[{"id":"light-sources-luminaires","name":"Электрические источники света. Осветительная арматура","materials":["light-sources-luminaires-lecture"]},{"id":"lighting-installation-repair","name":"Технология монтажа и ремонта светильников общего применения","materials":["lighting-installation-repair-lecture"]}]},{"id":"mdk-04-02-1eo-24-s3","name":"МДК 04.02 Организация работ по сборке, монтажу и ремонту электрооборудования","semester":3,"contentPath":"groups/1eo-24/mdk-04-02/semester-3","topics":[{"id":"undervoltage-release-light-sensor","name":"Монтаж, наладка и ремонт схемы, содержащей расцепитель минимального напряжения и датчик освещённости","materials":["undervoltage-release-light-sensor-lecture","undervoltage-release-light-sensor-practice"]},{"id":"three-phase-meter-connection","name":"Монтаж, наладка и ремонт схемы подключения трёхфазного электронного счётчика","materials":["three-phase-meter-connection-practice"]}]},{"id":"mdk-04-01","name":"МДК 04.01 Основы слесарно-сборочных и электромонтажных работ","contentPath":"groups/1eo-25/mdk-04-01","topics":[]},{"id":"op-08","name":"ОП.08 Информационные технологии в профессиональной деятельности","contentPath":"groups/1eo-24/op-08","topics":[{"id":"math-software-packages","name":"Общая характеристика пакетов прикладных программ для математических расчётов","materials":["math-software-packages-lecture"]}]},{"id":"op-12","name":"ОП.12 Правовые основы профессиональной деятельности","contentPath":"groups/1eo-24/op-12","topics":[{"id":"constitutional-system","name":"Конституционный строй: форма правления, форма государственного устройства и политический режим","materials":["constitutional-system-lecture"]}]},{"id":"op-03","name":"ОП.03 Электротехника и электроника","contentPath":"groups/1a-25-3a-26-11/op-03","topics":[{"id":"electromagnetism","name":"Электромагнетизм и электромагнитная индукция","materials":["electromagnetism-lecture"]}]}],"materials":[{"id":"undervoltage-release-light-sensor-lecture","type":"lecture","name":"Лекция","description":"Расцепитель минимального напряжения: устройство, уставки, применение и расчёт","file":"content/groups/1eo-24/mdk-04-02/semester-3/undervoltage-release-light-sensor/Лекция (расцепитель).html"},{"id":"undervoltage-release-light-sensor-practice","type":"practice","name":"Практическая работа","description":"Расчёт параметров схемы с расцепителем минимального напряжения и датчиком освещённости","file":"content/groups/1eo-24/mdk-04-02/semester-3/undervoltage-release-light-sensor/Практическая работа.html"},{"id":"constitutional-system-lecture","type":"lecture","name":"Лекция","description":"Конституционный строй: форма правления, форма государственного устройства и политический режим","file":"content/groups/1eo-24/op-12/constitutional-system/Лекция.html"},{"id":"math-software-packages-lecture","type":"lecture","name":"Лекция","description":"Общая характеристика пакетов прикладных программ для математических расчётов","file":"content/groups/1eo-24/op-08/math-software-packages/Лекция.html"},{"id":"switch-socket-connection-practice","type":"practice","name":"Практическая работа","description":"Подключение выключателей и розеток: схемы и технологические карты","file":"content/groups/1me-25/mdk-05-02/switch-socket-connection/Практическая работа.html"},{"id":"light-sources-luminaires-lecture","type":"lecture","name":"Лекция","description":"Электрические источники света. Осветительная арматура","file":"content/groups/1eo-25/mdk-04-02/semester-1/light-sources-luminaires/Лекция.html"},{"id":"electromagnetism-lecture","type":"lecture","name":"Лекция","description":"Электромагнетизм и электромагнитная индукция","file":"content/groups/1a-25-3a-26-11/op-03/electromagnetism/Лекция.html"},{"id":"lighting-network-check-practice","type":"practice","name":"Практическая работа","description":"Проверка осветительной сети: расчёт потери напряжения, выбор кабеля и аппарата защиты","file":"content/groups/1me-25/mdk-05-02/lighting-network-check/Практическая работа.html"},{"id":"three-phase-meter-connection-practice","type":"practice","name":"Практическая работа","description":"Монтаж, наладка и ремонт схемы подключения трёхфазного электронного счётчика","file":"content/groups/1eo-24/mdk-04-02/semester-3/three-phase-meter-connection/Практическая работа.html"},{"id":"lighting-installation-repair-lecture","type":"lecture","name":"Лекция","description":"Технология монтажа и ремонта светильников общего применения","file":"content/groups/1eo-25/mdk-04-02/semester-1/lighting-installation-repair/Лекция.html"}]};
window.ELECTROBAZA_CONTENT = {"undervoltage-release-light-sensor-lecture":"  <p>Расцепитель минимального напряжения — это электромагнитный аппарат, который удерживает коммутационный аппарат (автоматический выключатель, контактор или пускатель) во включённом положении, пока напряжение на его катушке достаточно. При недопустимом снижении напряжения расцепитель отпускает якорь, и аппарат отключает нагрузку. Так защищают оборудование от работы на пониженном напряжении: двигатель при этом перегревается, а электронные устройства дают сбои.</p>\n<section>\n  <h2>Как он выглядит</h2>\n  <p>В низковольтных щитах расцепитель выполняют в виде отдельного модуля, который встраивают в аппарат или присоединяют к нему сбоку. Автоматический выключатель без такого модуля защищает только от токов перегрузки и короткого замыкания.</p>\n  <figure>\n    <img src=\"content/groups/1eo-24/mdk-04-02/semester-3/undervoltage-release-light-sensor/images/cb-2pole-din.jpg\" alt=\"Автоматический выключатель IEK BA47-29 C16\" />\n    <figcaption>Рисунок 1 — Автоматический выключатель IEK BA47-29 C16.</figcaption>\n  </figure>\n  <figure>\n    <img src=\"content/groups/1eo-24/mdk-04-02/semester-3/undervoltage-release-light-sensor/images/rele-iek-ar-aux-ux21.png\" alt=\"Расцепитель минимального напряжения IEK ARMAT AR-AUX-UX21, Ue 230 В\" />\n    <figcaption>Рисунок 2 — Расцепитель минимального напряжения IEK ARMAT AR-AUX-UX21, Ue 230 В.</figcaption>\n  </figure>\n  <p>Модуль расцепителя имеет две клеммы для цепи управления (у этого аппарата — D1 и D2) и механически связан с замком аппарата. На контакторах роль расцепителя часто выполняет сама втягивающая катушка: при потере напряжения она отпускает якорь с главными контактами.</p>\n  <figure>\n    <img src=\"content/groups/1eo-24/mdk-04-02/semester-3/undervoltage-release-light-sensor/images/contactor-iek.jpg\" alt=\"Контактор IEK КМИ-11610: клеммы катушки А1 и А2\" />\n    <figcaption>Рисунок 3 — Контактор IEK КМИ-11610: клеммы катушки А1 и А2.</figcaption>\n  </figure>\n</section>\n<section>\n  <h2>Устройство и принцип действия</h2>\n  <p>Основные части расцепителя: катушка с магнитопроводом, подвижный якорь, возвратная пружина и толкатель (ударник). Катушку питают от той же цепи, напряжение которой контролируют, либо от отдельного источника: пока напряжение в норме, якорь притянут и удерживает замок, а при снижении напряжения ниже уставки пружина отпускает якорь, и аппарат размыкается. После восстановления напряжения аппарат сам не включается — его взводят вручную.</p>\n  <p>На схеме расцепитель обозначают прямоугольником с подписью U&lt;. Катушку включают между фазой и нейтралью на клеммах D1 и D2 (на контакторах — А1 и А2), а пунктирная линия обозначает механическую связь с коммутируемым аппаратом.</p>\n  <figure>\n    <img src=\"content/groups/1eo-24/mdk-04-02/semester-3/undervoltage-release-light-sensor/images/schema-uk.png\" alt=\"Схема включения расцепителя минимального напряжения: катушка U&lt; на клеммах D1 и D2, пунктирная линия — механическая связь с контактором\" />\n    <figcaption>Рисунок 4 — Схема включения расцепителя минимального напряжения: катушка U&lt; на клеммах D1 и D2, пунктирная линия — механическая связь с контактором.</figcaption>\n  </figure>\n  <p>Значения напряжения, при которых расцепитель обязан удерживать и обязан отпускать аппарат, заданы стандартом.</p>\n  <table>\n    <thead>\n      <tr><th>Напряжение на катушке</th><th>Поведение расцепителя</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>0,85 Uн и выше</td><td>аппарат должен надёжно удерживаться</td></tr>\n      <tr><td>0,35…0,7 Uн</td><td>аппарат должен отключиться</td></tr>\n      <tr><td>0 Uн</td><td>аппарат остаётся отключённым</td></tr>\n    </tbody>\n  </table>\n  <p>В расчётах удобно принимать уставку отпускания U<sub>отп</sub> = 0,5 Uн. Сопротивление катушки растёт при нагреве, поэтому уставку проверяют и при рабочей температуре.</p>\n</section>\n<section>\n  <h2>Применение</h2>\n  <p>Расцепитель минимального напряжения защищает электродвигатели и насосы от работы при пониженном напряжении, исключает самозапуск оборудования после исчезновения и восстановления напряжения, отключает нагрузки при переходе на резервное или аварийное питание и блокирует оборудование, если пропало питание цепей управления.</p>\n</section>\n<section>\n  <h2>Расчёт параметров катушки</h2>\n  <p>Номинальный ток и сопротивление катушки определяют по её паспортным данным — номинальному напряжению Uн и мощности Pн:</p>\n  <ul class=\"formulas\">\n    <li>I<sub>н</sub> = P<sub>н</sub> / U<sub>н</sub></li>\n  </ul>\n  <ul class=\"formulas\">\n    <li>R<sub>к</sub> = U<sub>н</sub><sup>2</sup> / P<sub>н</sub></li>\n  </ul>\n  <p>Например, для катушки 24 В мощностью 3 Вт: Iн = 0,125 А, Rк = 192 Ом. Сопротивление катушки при нагреве растёт, и напряжение отпускания также увеличивается:</p>\n  <ul class=\"formulas\">\n    <li>R(θ) = R<sub>20</sub> · [1 + α · (θ − 20)]</li>\n  </ul>\n  <p>где α = 0,004 1/°C для меди. При нагреве до 40 °C сопротивление составляет 207,4 Ом, а напряжение отпускания — 12,96 В, то есть на 8 % выше значения при 20 °C. Катушку питают по проводам, поэтому учитывают потерю напряжения в линии:</p>\n  <ul class=\"formulas\">\n    <li>ΔU = 2 · ρ · l · I / S</li>\n  </ul>\n</section>\n<section>\n  <h2>Отличие от других расцепителей</h2>\n  <p>Независимый (шунтовой) расцепитель отключает аппарат при подаче напряжения на катушку, расцепитель максимального тока — при перегрузке или коротком замыкании, тепловой — при длительной перегрузке. Расцепитель минимального напряжения действует наоборот: он отключает аппарат, когда напряжение на катушке падает ниже уставки.</p>\n</section>\n<section>\n  <h2>Краткие выводы</h2>\n  <p>Расцепитель минимального напряжения удерживает аппарат, пока есть напряжение, и отключает его при снижении напряжения ниже уставки: удержание — при 0,85 Uн, отпускание — при 0,35…0,7 Uн. После восстановления напряжения аппарат не включается сам — это защита от самозапуска. Расчёт сводится к определению тока и сопротивления катушки, проверке уставки при нагреве и проверке потери напряжения в линии.</p>\n</section>\n<section>\n  <p><a href=\"content/groups/1eo-24/mdk-04-02/semester-3/undervoltage-release-light-sensor/docs/Лекция — Расцепитель минимального напряжения.docx\">Скачать лекцию в Word (.docx)</a></p>\n</section>\n","undervoltage-release-light-sensor-practice":"<section>\n  <h2>Цель работы</h2>\n  <p>Рассчитать цепь расцепителя минимального напряжения, делитель датчика освещённости и осветительную линию, построить графики и сделать вывод о работоспособности схемы. Работа выполняется расчётно, по варианту.</p>\n</section>\n\n<section>\n  <h2>Исходные данные</h2>\n  <p>Напряжение сети U<sub>с</sub> = 230 В; питание датчика U<sub>пит</sub> = 12 В; порог компаратора U<sub>пор</sub> = 2,5 В; расцепитель U<sub>н</sub> = 24 В, P<sub>н</sub> = 3 Вт; удельное сопротивление меди ρ = 0,0175 Ом·мм²/м; допустимая потеря напряжения ΔU<sub>доп</sub> = 3 %; cos φ = 1.</p>\n  <p>Данные варианта возьмите из таблицы 1.</p>\n  <table>\n    <caption>Таблица 1 — Варианты задания</caption>\n    <thead>\n      <tr><th>Вариант</th><th>P<sub>л</sub>, кВт</th><th>L<sub>л</sub>, м</th><th>E<sub>вкл</sub>, лк</th><th>h, %</th><th>l<sub>р</sub>, м</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>1</td><td>0,6</td><td>15</td><td>20</td><td>5</td><td>10</td></tr>\n      <tr><td>2</td><td>0,9</td><td>20</td><td>30</td><td>10</td><td>15</td></tr>\n      <tr><td>3</td><td>1,2</td><td>25</td><td>50</td><td>10</td><td>20</td></tr>\n      <tr><td>4</td><td>1,5</td><td>30</td><td>50</td><td>15</td><td>25</td></tr>\n      <tr><td>5</td><td>1,8</td><td>35</td><td>75</td><td>15</td><td>30</td></tr>\n      <tr><td>6</td><td>2,1</td><td>40</td><td>75</td><td>20</td><td>35</td></tr>\n      <tr><td>7</td><td>2,5</td><td>50</td><td>100</td><td>20</td><td>40</td></tr>\n      <tr><td>8</td><td>3,0</td><td>60</td><td>150</td><td>25</td><td>50</td></tr>\n    </tbody>\n  </table>\n  <p>Сопротивление фоторезистора приведено в таблице 2; для промежуточных значений E используйте линейную интерполяцию.</p>\n  <table>\n    <caption>Таблица 2 — Сопротивление фоторезистора</caption>\n    <thead>\n      <tr><th>E, лк</th><th>R<sub>ф</sub>, кОм</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>1</td><td>250</td></tr>\n      <tr><td>10</td><td>50</td></tr>\n      <tr><td>20</td><td>30</td></tr>\n      <tr><td>30</td><td>20</td></tr>\n      <tr><td>50</td><td>14</td></tr>\n      <tr><td>75</td><td>10</td></tr>\n      <tr><td>100</td><td>8</td></tr>\n      <tr><td>150</td><td>5,5</td></tr>\n      <tr><td>300</td><td>3,0</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section>\n  <h2>Расчётная часть</h2>\n  <p>Пример для варианта 8. Для своего варианта подставьте данные таблицы 1; порядок расчёта не меняется.</p>\n\n  <h3>1. Цепь расцепителя</h3>\n  <ul class=\"formulas\">\n    <li>I<sub>н</sub> = P<sub>н</sub> / U<sub>н</sub></li>\n    <li>R<sub>к</sub> = U<sub>н</sub><sup>2</sup> / P<sub>н</sub></li>\n    <li>U<sub>отп</sub> = 0,5 · U<sub>н</sub></li>\n    <li>U<sub>вкл</sub> = 0,85 · U<sub>н</sub></li>\n  </ul>\n  <ul>\n    <li>I<sub>н</sub> = 0,125 А.</li>\n    <li>R<sub>к</sub> = 192 Ом.</li>\n    <li>U<sub>отп</sub> = 12 В.</li>\n    <li>U<sub>вкл</sub> = 20,4 В.</li>\n    <li>При 40 °C: R = 207,4 Ом.</li>\n    <li>U<sub>отп</sub> = 12,96 В (+8 %).</li>\n    <li>При l<sub>р</sub> = 50 м, S = 1,5 мм²:</li>\n    <li>ΔU = 0,146 В.</li>\n    <li>U<sub>кат</sub> = 23,85 В, что выше 20,4 В.</li>\n    <li>P<sub>Σ</sub> = 4,7 Вт.</li>\n    <li>I<sub>Σ</sub> = 0,196 А.</li>\n    <li>Блок 24 В на 1,25 А подходит.</li>\n  </ul>\n\n  <h3>2. Датчик освещённости</h3>\n  <ul class=\"formulas\">\n    <li class=\"small\">R<sub>1</sub> = R<sub>ф</sub>(E<sub>вкл</sub>) · (U<sub>пит</sub> / U<sub>пор</sub> − 1)</li>\n    <li class=\"small\">U<sub>вых</sub> = U<sub>пит</sub> · R<sub>ф</sub> / (R<sub>1</sub> + R<sub>ф</sub>)</li>\n    <li>U<sub>отк</sub> = (1 − h) · U<sub>вкл</sub></li>\n  </ul>\n  <ul>\n    <li>При E<sub>вкл</sub> = 150 лк: R<sub>ф</sub> = 5,5 кОм.</li>\n    <li>R<sub>1</sub> = 5,5 · 3,8 = 20,9 кОм.</li>\n    <li>Принимаем R<sub>1</sub> = 20 кОм.</li>\n    <li>Порог 2,5 В: R<sub>ф</sub> = 5,26 кОм.</li>\n    <li>E<sub>вкл</sub> ≈ 164 лк.</li>\n    <li>При h = 25 %: U<sub>отк</sub> = 1,875 В.</li>\n    <li>R<sub>ф</sub> = 3,70 кОм.</li>\n    <li>E<sub>отк</sub> ≈ 258 лк.</li>\n    <li>Гистерезис 94 лк.</li>\n  </ul>\n  <p>Рассчитайте U<sub>вых</sub> для своего R<sub>1</sub> по таблице 2 и постройте график.</p>\n  <figure>\n    <img src=\"content/groups/1eo-24/mdk-04-02/semester-3/undervoltage-release-light-sensor/images/sensor-divider.svg\" alt=\"График выходного напряжения делителя с фоторезистором в зависимости от освещённости с порогами включения 164 люкс и отключения 258 люкс\" />\n    <figcaption>Рисунок 1 — Выходное напряжение делителя при R<sub>1</sub> = 20 кОм; штриховые линии — пороги (вариант 8)</figcaption>\n  </figure>\n\n  <h3>3. Осветительная линия</h3>\n  <ul class=\"formulas\">\n    <li>I<sub>л</sub> = P<sub>л</sub> / U<sub>с</sub></li>\n    <li>ΔU = 2 · ρ · L · I<sub>л</sub> / S</li>\n    <li>ΔU, % = 100 · ΔU / U<sub>с</sub></li>\n  </ul>\n  <ul>\n    <li>I<sub>л</sub> = 13,04 А.</li>\n    <li>Результаты — в таблице 3.</li>\n    <li>Принимаем 4 мм².</li>\n    <li>Лучше 6 мм² с запасом.</li>\n    <li>Автоматический выключатель B16.</li>\n  </ul>\n  <table>\n    <caption>Таблица 3 — Потеря напряжения при L = 60 м и I<sub>л</sub> = 13,04 А</caption>\n    <thead>\n      <tr><th>S, мм²</th><th>ΔU, В</th><th>ΔU, %</th><th>Проверка</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>1,5</td><td>18,26</td><td>7,94</td><td>не проходит</td></tr>\n      <tr><td>2,5</td><td>10,96</td><td>4,76</td><td>не проходит</td></tr>\n      <tr><td>4</td><td>6,85</td><td>2,98</td><td>проходит</td></tr>\n      <tr><td>6</td><td>4,57</td><td>1,98</td><td>проходит с запасом</td></tr>\n    </tbody>\n  </table>\n  <figure>\n    <img src=\"content/groups/1eo-24/mdk-04-02/semester-3/undervoltage-release-light-sensor/images/line-voltage-drop.svg\" alt=\"График потери напряжения в осветительной линии для кабелей 1,5, 2,5 и 4 квадратных миллиметра с допустимым уровнем 3 процента\" />\n    <figcaption>Рисунок 2 — Потеря напряжения в линии при P<sub>л</sub> = 3,0 кВт и I<sub>л</sub> = 13,04 А; штриховая линия — 3 % (вариант 8)</figcaption>\n  </figure>\n</section>\n\n<section>\n  <h2>Отчёт</h2>\n  <ul>\n    <li>номер варианта и исходные данные;</li>\n    <li>формулы и расчёты по заданиям 1–3;</li>\n    <li>таблицы 2–3 и графики 1–2;</li>\n    <li>вывод: выполняются ли условия по удержанию расцепителя, порогам датчика и потере напряжения; если нет — что изменить.</li>\n  </ul>\n</section>\n\n<section>\n  <h2>Контрольные вопросы</h2>\n  <ol>\n    <li>Почему расцепитель должен удерживаться при 0,85 U<sub>н</sub> и отпускать при 0,5 U<sub>н</sub>?</li>\n    <li>Как температура катушки влияет на напряжение отпускания?</li>\n    <li>Как сопротивление R<sub>1</sub> влияет на пороги включения и отключения?</li>\n    <li>Зачем датчику гистерезис и как его учесть в расчёте?</li>\n    <li>Почему кабель 1,5 мм² не проходит по потере напряжения при 60 м, хотя его допустимый ток больше 13 А?</li>\n  </ol>\n</section>\n\n<p><a href=\"content/groups/1eo-24/mdk-04-02/semester-3/undervoltage-release-light-sensor/docs/Практическая работа — Расчёт схемы.docx\">Скачать работу в Word (.docx)</a></p>\n","constitutional-system-lecture":"  <p>Конституционный строй — это система базовых принципов организации государства и общества, закреплённых Конституцией РФ 1993 г. (с поправками 2020 г.): народовластие, права и свободы человека, разделение властей, федерализм, правовое и социальное государство, идеологическое и политическое многообразие. Основы конституционного строя закреплены в главе 1 Конституции и защищены особым порядком пересмотра.</p>\n<section>\n  <h2>Форма государства</h2>\n  <p>Форма государства описывает, как организована и осуществляется государственная власть. Она включает три взаимосвязанные характеристики; их единство и образует форму конкретного государства.</p>\n  <figure>\n    <img src=\"content/groups/1eo-24/op-12/constitutional-system/images/schema-forma-gosudarstva-mobile.svg\" alt=\"Три характеристики формы государства: форма правления, форма государственного устройства и политический режим\" />\n    <figcaption>Рисунок 1 — Три характеристики формы государства: форма правления, форма государственного устройства и политический режим.</figcaption>\n  </figure>\n</section>\n<section>\n  <h2>1. Форма правления</h2>\n  <p>Форма правления — способ организации верховной государственной власти, порядок формирования её органов и их взаимодействия. Монархия передаёт власть по наследству, республика избирает главу государства на срок. Конституция РФ устанавливает республиканскую форму правления (ст. 1). По соотношению полномочий Президента, Правительства и Государственной Думы Россия является смешанной (полупрезидентской) республикой: Президент — глава государства и гарант Конституции (ст. 80), Правительство осуществляет исполнительную власть (ст. 110), Дума участвует в формировании Правительства и может выразить ему недоверие, а Президент вправе отправить Правительство в отставку.</p>\n  <table>\n    <caption>Таблица 1 — Формы правления</caption>\n    <thead>\n      <tr><th>Форма правления</th><th>Правительство и ответственность</th><th>Примеры</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>Президентская республика</td><td>Формирует президент; ответственно перед президентом</td><td>США, Бразилия</td></tr>\n      <tr><td>Парламентская республика</td><td>Формирует парламент; ответственно перед парламентом</td><td>Германия, Италия</td></tr>\n      <tr><td>Смешанная республика</td><td>Формируют президент и парламент; ответственно перед обоими</td><td>Россия, Франция</td></tr>\n    </tbody>\n  </table>\n</section>\n<section>\n  <h2>2. Форма государственного устройства</h2>\n  <p>Форма государственного устройства — территориальная организация государства и соотношение полномочий центра и регионов. В унитарном государстве действует единая система власти, а регионы не обладают суверенитетом. Федерация состоит из субъектов, имеющих собственные органы и предметы ведения. Конфедерация — союз государств для ограниченных общих целей. Россия — федерация (ст. 1, 5): государственная целостность, единство системы власти, разграничение предметов ведения, равноправие субъектов. Субъекты перечислены в ст. 65, разграничение предметов ведения — ст. 71–73.</p>\n  <table>\n    <caption>Таблица 2 — Формы государственного устройства</caption>\n    <thead>\n      <tr><th>Форма устройства</th><th>Признаки</th><th>Примеры</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>Унитарное государство</td><td>Единая конституция и система органов; регионы без суверенитета</td><td>Франция, Япония</td></tr>\n      <tr><td>Федерация</td><td>Субъекты имеют органы власти и предметы ведения</td><td>Россия, США, Германия</td></tr>\n      <tr><td>Конфедерация</td><td>Союз государств для ограниченных целей</td><td>Исторические союзы; встречается редко</td></tr>\n    </tbody>\n  </table>\n</section>\n<section>\n  <h2>3. Политический режим</h2>\n  <p>Политический режим — совокупность методов и средств осуществления государственной власти, положение личности, отношение к оппозиции. Конституция РФ закрепляет основы демократического режима: народ — носитель суверенитета и единственный источник власти (ст. 3); признаются идеологическое и политическое многообразие, многопартийность (ст. 13); гарантируются права и свободы, разделение властей (ст. 10), местное самоуправление (ст. 12); граждане участвуют в управлении через выборы и референдум.</p>\n  <p>Недемократические режимы различаются степенью контроля. При авторитарном власть сосредоточена у одного лица или группы, оппозиция ограничена, но частная жизнь относительно свободна. При тоталитарном государство контролирует все сферы, существует единая обязательная идеология, подавляется инакомыслие.</p>\n</section>\n<section>\n  <h2>4. Как связаны три характеристики</h2>\n  <p>Три характеристики взаимосвязаны, но не совпадают. Республика может быть демократической или авторитарной, федерация — демократической или централизованной, унитарное государство — демократическим. Поэтому о режиме нельзя судить только по форме правления: конституционная модель задаёт рамки, а реализация зависит от политической практики.</p>\n</section>\n<section>\n  <h2>Вывод</h2>\n  <p>Россия по Конституции — демократическое федеративное правовое государство с республиканской формой правления. Это означает смешанную республику, федеративное устройство и демократический политический режим как конституционную основу. Юристу важно различать формальные признаки формы государства и их фактическую реализацию.</p>\n</section>\n<section>\n  <h2>Контрольные вопросы</h2>\n  <ol>\n    <li>Что такое конституционный строй и какие принципы относятся к его основам?</li>\n    <li>Чем президентская республика отличается от парламентской?</li>\n    <li>Почему Россию относят к смешанным республикам? Назовите не менее трёх признаков.</li>\n    <li>Какие признаки отличают федерацию от унитарного государства?</li>\n    <li>Может ли федерация быть недемократической? Приведите пример и объясните связь формы устройства и политического режима.</li>\n  </ol>\n</section>\n<p><a href=\"content/groups/1eo-24/op-12/constitutional-system/docs/Лекция — Конституционный строй.docx\">Скачать лекцию в Word (.docx)</a></p>\n","math-software-packages-lecture":"  <p>Пакеты прикладных программ (ППП) — это готовые программные комплексы для решения задач определённого класса. Вместо написания программы с нуля пользователь задаёт исходные данные, выбирает метод или команду и получает результат. Для математических расчётов такие пакеты особенно важны: они берут на себя вычисления, построение графиков и оформление отчёта.</p>\n<section>\n  <h2>Цель и ключевые понятия</h2>\n  <p>Цель лекции — понять, какие пакеты применяются для математических расчётов, чем они различаются и как выбрать подходящий инструмент.</p>\n  <p>Пакет прикладных программ — это набор взаимосвязанных программ и средств, предназначенных для автоматизации задач в конкретной предметной области. Математический пакет ориентирован на численные и символьные вычисления, обработку данных и визуализацию.</p>\n  <p>В типичный математический пакет входят:</p>\n  <ul>\n    <li>вычислительное ядро — выполняет операции и алгоритмы;</li>\n    <li>интерфейс — позволяет задавать данные и команды без программирования;</li>\n    <li>библиотеки функций — содержат готовые математические методы;</li>\n    <li>средства визуализации — строят графики, диаграммы и поверхности;</li>\n    <li>средства документирования — сохраняют расчёт и пояснения в одном документе.</li>\n  </ul>\n</section>\n<section>\n  <h2>Классификация</h2>\n  <p>По способу работы и области применения выделяют четыре основные группы пакетов.</p>\n  <figure>\n    <img src=\"content/groups/1eo-24/op-08/math-software-packages/images/schema-math-packages-mobile.svg\" alt=\"Классификация пакетов прикладных программ для математических расчётов\" />\n    <figcaption>Рисунок 1 — Классификация пакетов прикладных программ для математических расчётов.</figcaption>\n  </figure>\n  <ul>\n    <li><strong>Универсальные математические пакеты</strong> — MathCAD, MATLAB, Mathematica, Maple. Позволяют выполнять численные и символьные расчёты, строить графики и оформлять инженерные документы.</li>\n    <li><strong>Табличные процессоры</strong> — Excel, LibreOffice Calc. Удобны для массовых расчётов по формулам, обработки таблиц, построения диаграмм и простых моделей.</li>\n    <li><strong>Среды программирования</strong> — Python с библиотеками NumPy, SciPy, Matplotlib, а также R. Дают гибкость, воспроизводимость и возможность автоматизировать сложные расчёты.</li>\n    <li><strong>Специализированные инженерные программы</strong> — CAD/CAE-системы и прикладные расчёты вроде «Электрика». Работают по готовым методикам для узких профессиональных задач.</li>\n  </ul>\n</section>\n<section>\n  <h2>Обзор пакетов</h2>\n  <p>MathCAD удобен для инженерных расчётов: формулы записываются в привычном виде, поддерживаются единицы измерения и документирование. MATLAB силён в матричных вычислениях, моделировании и обработке сигналов; его применяют в науке и технике. Табличный процессор доступен почти на любом компьютере и хорошо подходит для расчётов по формулам и диаграмм. Python выбирают, когда нужна автоматизация, повторяемые сценарии и работа с большими данными.</p>\n  <table>\n    <caption>Таблица 1 — Сравнение пакетов для математических расчётов</caption>\n    <thead>\n      <tr><th>Пакет</th><th>Назначение</th><th>Особенности</th></tr>\n    </thead>\n    <tbody>\n      <tr><td>MathCAD</td><td>Инженерные и математические расчёты</td><td>Формулы в естественной записи, единицы измерения</td></tr>\n      <tr><td>MATLAB</td><td>Матричные вычисления и моделирование</td><td>Toolboxes, Simulink, обработка данных</td></tr>\n      <tr><td>Excel / LibreOffice Calc</td><td>Табличные расчёты и диаграммы</td><td>Доступность, простые формулы, отчёты</td></tr>\n      <tr><td>Python (NumPy, SciPy)</td><td>Программируемые расчёты и автоматизация</td><td>Библиотеки, сценарии, воспроизводимость</td></tr>\n    </tbody>\n  </table>\n  <p>Выбор зависит от задачи, требуемой точности, навыков пользователя и необходимости оформить отчёт. Для разового расчёта часто достаточно таблицы, для серии однотипных задач — сценария на Python, для сложной инженерной модели — специализированного пакета.</p>\n</section>\n<section>\n  <h2>Как выбрать пакет</h2>\n  <p>При выборе пакета учитывают не только набор функций, но и условия работы.</p>\n  <ul>\n    <li>тип задачи: разовый расчёт, серия однотипных задач, символьные преобразования или моделирование;</li>\n    <li>объём данных: небольшая таблица или тысячи строк, которые нужно обрабатывать регулярно;</li>\n    <li>требования к отчёту: нужны ли формулы, графики, единицы измерения и пояснения в одном документе;</li>\n    <li>навыки пользователя: готовый интерфейс удобнее, программирование даёт больше гибкости;</li>\n    <li>доступность и лицензия: установлен ли пакет, можно ли использовать бесплатную версию.</li>\n  </ul>\n  <p>Для учебных расчётов часто достаточно табличного процессора; для инженерных задач с формулами и единицами измерения подходит MathCAD; для автоматизации и больших данных — Python.</p>\n</section>\n<section>\n  <h2>Примеры применения и короткий расчёт</h2>\n  <p>В профессиональной деятельности пакеты применяют для расчёта электрических цепей, проводников и нагрузок, обработки результатов измерений, построения графиков и оформления пояснительных записок.</p>\n  <p>Специализированные программы берут на себя готовые методики. Например, программа «Электрик» помогает подбирать проводники и кабели по току, потере напряжения и условиям прокладки.</p>\n  <figure>\n    <img src=\"content/groups/1eo-24/op-08/math-software-packages/images/elektrik-v7-8.png\" alt=\"Интерфейс программы «Электрик» для расчёта проводников и кабелей\" />\n    <figcaption>Рисунок 2 — Интерфейс программы «Электрик» для расчёта проводников и кабелей.</figcaption>\n  </figure>\n  <p>Короткий пример. Требуется вычислить значения функции и их сумму для x = 1, 2, 3.</p>\n  <ul class=\"formulas\">\n    <li>y = (x² + 3x) / (x + 1)</li>\n  </ul>\n  <ul>\n    <li>при x = 1: y = 2,00;</li>\n    <li>при x = 2: y = 3,33;</li>\n    <li>при x = 3: y = 4,50;</li>\n    <li>сумма значений: 9,83.</li>\n  </ul>\n  <p>В табличном процессоре формула записывается один раз и копируется на все строки; в MathCAD или Python её можно сразу использовать для серии исходных данных. Главное — проверить единицы измерения и исходные значения.</p>\n</section>\n<section>\n  <h2>Типичные ошибки</h2>\n  <ul>\n    <li>неверные единицы измерения: миллиметры и метры, ватты и киловатты;</li>\n    <li>округление промежуточных результатов сильнее, чем требуется по условию;</li>\n    <li>использование готовой функции без понимания метода и области его применимости;</li>\n    <li>устаревшие исходные данные или версия программы, которая отличается от методики.</li>\n  </ul>\n  <p>Поэтому результат расчёта всегда проверяют независимой оценкой: порядком величины, простым контрольным примером или расчётом другим способом.</p>\n</section>\n<section>\n  <h2>Выводы</h2>\n  <ul>\n    <li>Пакеты прикладных программ экономят время и уменьшают число ручных ошибок.</li>\n    <li>Универсальные пакеты подходят для сложных расчётов, табличные — для массовых и наглядных.</li>\n    <li>Среды программирования дают гибкость и воспроизводимость, специализированные программы — готовые методики.</li>\n    <li>Выбор пакета определяется задачей, точностью, навыками и требованиями к отчёту.</li>\n  </ul>\n  <p>Главное — не подменять понимание расчёта нажатием кнопки: пакет ускоряет работу, но исходные данные, метод и результат проверяет человек.</p>\n</section>\n<section>\n  <h2>Вопросы для самопроверки</h2>\n  <ol>\n    <li>Чем пакет прикладных программ отличается от универсальной программы?</li>\n    <li>Какие четыре группы математических пакетов выделяют?</li>\n    <li>Для каких задач удобнее табличный процессор?</li>\n    <li>Почему при работе со специализированной программой нужно проверять исходные данные?</li>\n    <li>Как выбрать пакет для расчёта, который нужно оформить в виде отчёта?</li>\n  </ol>\n</section>\n<p><a href=\"content/groups/1eo-24/op-08/math-software-packages/docs/Лекция — Пакеты прикладных программ для математических расчётов.docx\">Скачать лекцию в Word (.docx)</a></p>\n","switch-socket-connection-practice":"<section>  <h2>Цель работы</h2>  <p>Изучить схемы подключения выключателей и розеток, определить назначение проводников и составить технологические карты монтажа розетки и одноклавишного выключателя.</p></section>\n<section>  <h2>Краткие сведения</h2>  <ul>    <li>Выключатель разрывает фазный провод; ноль и защитное заземление через него не коммутируются.</li>    <li>В розетке с заземлением три контакта: L — фаза, N — ноль, PE — защитное заземление.</li>    <li>Обычно фаза — коричневый или чёрный провод, ноль — синий, PE — жёлто-зелёный; цвета проверяют по маркировке кабеля.</li>    <li>Соединения выполняют в распределительных коробках и подрозетниках, а не в штробе.</li>    <li>Одноклавишный выключатель имеет два контакта, двухклавишный — три, проходной — три контакта с переключением.</li>  </ul></section>\n<section>  <h2>Схемы подключения</h2>  <figure>\n    <img src=\"content/groups/1me-25/mdk-05-02/switch-socket-connection/images/one-gang-switch.png\" alt=\"Схема подключения одноклавишного выключателя через распределительную коробку\" />\n    <figcaption>Схема 1 — Одноклавишный выключатель.</figcaption>\n  </figure>  <figure>\n    <img src=\"content/groups/1me-25/mdk-05-02/switch-socket-connection/images/two-gang-switch.png\" alt=\"Схема подключения двухклавишного выключателя к двум лампам\" />\n    <figcaption>Схема 2 — Двухклавишный выключатель.</figcaption>\n  </figure>  <figure>\n    <img src=\"content/groups/1me-25/mdk-05-02/switch-socket-connection/images/pass-through-switch.png\" alt=\"Схема подключения проходного выключателя с двумя распределительными коробками\" />\n    <figcaption>Схема 3 — Проходной выключатель.</figcaption>\n  </figure>  <figure>\n    <img src=\"content/groups/1me-25/mdk-05-02/switch-socket-connection/images/socket-grounding.png\" alt=\"Розетка с заземляющим контактом и розетка без заземляющего контакта\" />\n    <figcaption>Схема 4 — Розетка: с заземлением и без заземления.</figcaption>\n  </figure>  <figure>\n    <img src=\"content/groups/1me-25/mdk-05-02/switch-socket-connection/images/switch-socket-block.png\" alt=\"Схема подключения блока «одноклавишный выключатель и розетка»\" />\n    <figcaption>Схема 5 — Блок «выключатель + розетка».</figcaption>\n  </figure></section>\n<section>  <h2>Типичные ошибки</h2>  <ul>    <li>выключатель разрывает ноль вместо фазы;</li>    <li>PE и N перепутаны в розетке;</li>    <li>соединения выполнены в штробе, а не в коробке;</li>    <li>недостаточный запас жил в подрозетнике;</li>    <li>розетка с заземлением подключена без PE;</li>    <li>проходной выключатель подключён как обычный;</li>    <li>в блоке «выключатель + розетка» перепутаны цепи питания.</li>  </ul></section>\n<section>  <h2>Отчёт</h2>  <ol>    <li>Цель работы и краткие сведения;</li>    <li>Пять схем подключения;</li>    <li>Технологическая карта монтажа одноклавишного выключателя;</li>    <li>Разбор типичных ошибок;</li>    <li>Вывод.</li>  </ol></section>\n<section>  <h2>Приложение 1. Технологическая карта: розетка (образец)</h2>  <p>Подключение розетки с заземлением.</p><p class=\"table-hint\">Таблица прокручивается по горизонтали →</p><div class=\"table-scroll\">\n  <table class=\"tech-map\">\n    <caption>Таблица 1 — Технологическая карта: розетка (образец)</caption>\n    <thead>\n      <tr>\n        <th scope=\"col\">№ п/п</th>\n        <th scope=\"col\">Наименование операций</th>\n        <th scope=\"col\">Эскиз или место выполнения</th>\n        <th scope=\"col\">Оборудование и приспособления</th>\n        <th scope=\"col\">Инструмент</th>\n        <th scope=\"col\">Норма времени, мин</th>\n        <th scope=\"col\">Разряд исполнителя</th>\n        <th scope=\"col\">Технические условия и дополнительные требования</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr>\n        <td>1</td>\n        <td>Изучить схему и маркировку</td>\n        <td>Рабочее место; схема подключения</td>\n        <td>Схема, кабельный журнал</td>\n        <td>Маркер</td>\n        <td>5</td>\n        <td>3</td>\n        <td>Определить L, N, PE. Сверить схему с заданием.</td>\n      </tr>\n      <tr>\n        <td>2</td>\n        <td>Обесточить линию</td>\n        <td>Распределительный щит</td>\n        <td>—</td>\n        <td>Индикатор напряжения, отвертка</td>\n        <td>5</td>\n        <td>3</td>\n        <td>Убедиться в отсутствии напряжения на всех полюсах. Вывесить предупреждение.</td>\n      </tr>\n      <tr>\n        <td>3</td>\n        <td>Разметить место установки</td>\n        <td>Стена; место подрозетника</td>\n        <td>Уровень, шаблон</td>\n        <td>Маркер, рулетка</td>\n        <td>8</td>\n        <td>3</td>\n        <td>Высота — по заданию. Проверить горизонтальность и удобство.</td>\n      </tr>\n      <tr>\n        <td>4</td>\n        <td>Подготовить гнездо и установить подрозетник</td>\n        <td>Стена; гнездо подрозетника</td>\n        <td>Перфоратор, пылесос, подрозетник</td>\n        <td>Бур, уровень, шпатель</td>\n        <td>15</td>\n        <td>3</td>\n        <td>Глубина — по толщине механизма. Подрозетник установить заподлицо. Кабель завести с запасом 10–15 см.</td>\n      </tr>\n      <tr>\n        <td>5</td>\n        <td>Завести кабель</td>\n        <td>Подрозетник, распределительная коробка</td>\n        <td>—</td>\n        <td>Стриппер, бокорезы</td>\n        <td>8</td>\n        <td>3</td>\n        <td>Не повредить изоляцию. Соблюдать радиус изгиба. Выполнить маркировку.</td>\n      </tr>\n      <tr>\n        <td>6</td>\n        <td>Разделать жилы</td>\n        <td>Подрозетник</td>\n        <td>—</td>\n        <td>Стриппер</td>\n        <td>7</td>\n        <td>3</td>\n        <td>Зачистка жил 8–10 мм. Не повредить PE. Удалить загрязнения.</td>\n      </tr>\n      <tr>\n        <td>7</td>\n        <td>Подключить розетку</td>\n        <td>Подрозетник</td>\n        <td>Розетка с заземляющим контактом</td>\n        <td>Отвертка, индикатор</td>\n        <td>10</td>\n        <td>3</td>\n        <td>L — фаза, N — ноль, PE — заземление. Затяжка клемм 0,8–1,2 Н·м. PE не коммутировать.</td>\n      </tr>\n      <tr>\n        <td>8</td>\n        <td>Установить механизм и рамку</td>\n        <td>Подрозетник</td>\n        <td>Механизм, рамка</td>\n        <td>Отвертка</td>\n        <td>5</td>\n        <td>3</td>\n        <td>Не защемить жилы. Рамка без перекосов. Механизм закрепить надежно.</td>\n      </tr>\n      <tr>\n        <td>9</td>\n        <td>Проверить</td>\n        <td>Розетка</td>\n        <td>Тестер или индикатор</td>\n        <td>Индикатор, отвертка</td>\n        <td>10</td>\n        <td>3</td>\n        <td>Проверить PE, полярность, затяжку клемм и маркировку.</td>\n      </tr>\n      <tr>\n        <td>10</td>\n        <td>Сдать работу</td>\n        <td>Рабочее место</td>\n        <td>—</td>\n        <td>—</td>\n        <td>5</td>\n        <td>3</td>\n        <td>Заполнить отчёт. Убрать рабочее место.</td>\n      </tr>\n    </tbody>\n  </table>\n</div></section>\n<section>  <h2>Приложение 2. Технологическая карта: выключатель (бланк)</h2>  <p>Подключение одноклавишного выключателя.</p><p class=\"table-hint\">Таблица прокручивается по горизонтали →</p><div class=\"table-scroll\">\n  <table class=\"tech-map\">\n    <caption>Таблица 2 — Технологическая карта: выключатель (бланк)</caption>\n    <thead>\n      <tr>\n        <th scope=\"col\">№ п/п</th>\n        <th scope=\"col\">Наименование операций</th>\n        <th scope=\"col\">Эскиз или место выполнения</th>\n        <th scope=\"col\">Оборудование и приспособления</th>\n        <th scope=\"col\">Инструмент</th>\n        <th scope=\"col\">Норма времени, мин</th>\n        <th scope=\"col\">Разряд исполнителя</th>\n        <th scope=\"col\">Технические условия и дополнительные требования</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr>\n        <td>1</td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n      </tr>\n      <tr>\n        <td>2</td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n      </tr>\n      <tr>\n        <td>3</td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n      </tr>\n      <tr>\n        <td>4</td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n      </tr>\n      <tr>\n        <td>5</td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n      </tr>\n      <tr>\n        <td>6</td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n      </tr>\n      <tr>\n        <td>7</td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n      </tr>\n      <tr>\n        <td>8</td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n      </tr>\n      <tr>\n        <td>9</td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n      </tr>\n      <tr>\n        <td>10</td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n        <td></td>\n      </tr>\n    </tbody>\n  </table>\n</div></section>\n<p><a href=\"content/groups/1me-25/mdk-05-02/switch-socket-connection/docs/Практическая работа — Подключение выключателей и розеток.docx\">Скачать работу в Word (.docx)</a></p>\n","light-sources-luminaires-lecture":"<p>Осветительная электроустановка начинается с источника света и светильника. Источник создаёт световой поток, а арматура направляет его, защищает лампу и обеспечивает безопасную работу. От правильного выбора этой пары зависят освещённость, расход электроэнергии и условия труда.</p>\n\n<section>\n  <h2>Классификация источников света</h2>\n  <p>По принципу преобразования энергии источники света делят на три группы.</p>\n  <ul>\n    <li><strong>Тепловые</strong> — лампа накаливания и галогенная лампа. Свет создаётся нагревом нити. Они просты и работают сразу, но имеют низкую световую отдачу и сильно нагреваются.</li>\n    <li><strong>Газоразрядные</strong> — люминесцентные, ДРЛ (дуговая ртутная люминофорная лампа), ДНаТ (дуговая натриевая трубчатая лампа) и металлогалогенные. Свет возникает при электрическом разряде в газе или парах металла. Экономичнее, но требуют пускорегулирующей аппаратуры.</li>\n    <li><strong>Светодиодные</strong> — полупроводниковые модули. Экономичны, долговечны и хорошо регулируются, но требуют драйвера и отвода тепла.</li>\n  </ul>\n</section>\n\n<section>\n  <h2>Газоразрядные лампы</h2>\n  <p>Газоразрядная лампа — стеклянная колба с газом или парами металла и электродами. При подаче напряжения возникает разряд, который возбуждает атомы газа; излучение превращается в видимый свет напрямую или через люминофор.</p>\n  <p>Для поджига и стабилизации режима нужна пускорегулирующая аппаратура: дроссель, стартер или электронный балласт. Она ограничивает ток и не даёт лампе выйти из строя.</p>\n  <p>Основные типы: люминесцентные лампы — для офисов, учебных и производственных помещений; лампы ДРЛ — ртутные лампы высокого давления; лампы ДНаТ — натриевые, с жёлто-оранжевым светом; металлогалогенные — мощные лампы с хорошей цветопередачей для прожекторов и больших цехов.</p>\n  <p>Достоинства — высокая световая отдача и большой срок службы. Недостатки — балласт, время разгорания, чувствительность к температуре, наличие ртути у части ламп и специальная утилизация.</p>\n  <figure>\n    <img src=\"content/groups/1eo-25/mdk-04-02/semester-1/light-sources-luminaires/images/fluorescent-circuit.png\" alt=\"Схема подключения люминесцентной лампы с дросселем и стартером\" />\n    <figcaption>Рисунок 1 — Схема подключения люминесцентной лампы с дросселем и стартером.</figcaption>\n  </figure>\n</section>\n\n<section>\n  <h2>Светодиодные источники</h2>\n  <p>Светодиод — полупроводниковый прибор, излучающий свет при прохождении тока. В светильниках применяют сборки и модули из нескольких кристаллов.</p>\n  <p>Светодиодный светильник включает светодиодный модуль, драйвер, радиатор или корпус для отвода тепла и оптическую систему — линзы, отражатель или рассеиватель.</p>\n  <p>Преимущества — высокая световая отдача, большой срок службы, мгновенное включение, регулирование яркости и цвета, отсутствие ртути. Ограничения — стоимость, чувствительность к перегреву и качеству драйвера, риск пульсации и неудачного спектра.</p>\n  <p>Для промышленного применения важны не только люмены, но и качество света: цветопередача, отсутствие пульсации, стабильность при перепадах температуры и надёжность драйвера.</p>\n  <figure>\n    <img src=\"content/groups/1eo-25/mdk-04-02/semester-1/light-sources-luminaires/images/led-lamp.png\" alt=\"Устройство светодиодной лампы: цоколь, драйвер, радиатор, плата со светодиодами и рассеиватель\" />\n    <figcaption>Рисунок 2 — Устройство светодиодной лампы: цоколь, драйвер, радиатор, плата со светодиодами и рассеиватель.</figcaption>\n  </figure>\n</section>\n\n<section>\n  <h2>Осветительная арматура</h2>\n  <p>Осветительная арматура — комплекс деталей, который вместе с источником света образует светильник. Она перераспределяет световой поток, защищает лампу от пыли, влаги и повреждений, обеспечивает крепление и подключение, защищает окружающую среду от нагрева и осколков.</p>\n  <p>Светильники различают по назначению, способу установки, степени защиты, светораспределению и конструкции. По распределению света выделяют прямые, рассеянные и отражённые светильники. Важны защитный угол и кривая силы света.</p>\n  <p>Для промышленных условий ключевыми являются степень защиты IP и вид исполнения: обычное, пылевлагозащищённое или взрывозащищённое. Нельзя ставить обычный светильник в сырое, пыльное или взрывоопасное помещение.</p>\n  <figure>\n    <img src=\"content/groups/1eo-25/mdk-04-02/semester-1/light-sources-luminaires/images/led-luminaire.png\" alt=\"Устройство светодиодного светильника с драйвером DALI\" />\n    <figcaption>Рисунок 3 — Устройство светодиодного светильника с драйвером DALI.</figcaption>\n  </figure>\n</section>\n\n<section>\n  <h2>Промышленное освещение</h2>\n  <p>Рабочее освещение обеспечивает нормальную работу на рабочих местах: нормируемую освещённость, равномерность, ограничение ослеплённости и пульсации.</p>\n  <p>Аварийное освещение включается при нарушении рабочего. Оно бывает эвакуационным — для выхода людей и резервным — для продолжения работы на ответственных участках. Светильники аварийного освещения должны отличаться от рабочих и питаться от независимого источника.</p>\n  <p>Охранное освещение устанавливают по периметру территории, переносное применяют для временных работ и ремонта. При выборе светильников для цеха учитывают высоту помещения, характер среды, взрывоопасные зоны, температуру, вибрацию и удобство обслуживания.</p>\n  <figure>\n    <img src=\"content/groups/1eo-25/mdk-04-02/semester-1/light-sources-luminaires/images/industrial-lighting.png\" alt=\"Освещение производственного цеха\" />\n    <figcaption>Рисунок 4 — Освещение производственного цеха.</figcaption>\n  </figure>\n</section>\n\n<section>\n  <h2>Особые условия среды</h2>\n  <p>В промышленности светильники работают в разных условиях: пыль, влага и брызги, химически активная среда, взрывоопасные зоны, высокая температура, вибрация. Для каждого случая выбирают соответствующее исполнение и степень защиты.</p>\n  <p>Взрывозащищённый светильник — это не просто герметичный корпус. Он должен иметь маркировку взрывозащиты и соответствовать классу зоны. Нельзя заменять лампу на более мощную, снимать защитные стёкла и уплотнения: это нарушает охлаждение, защиту IP и взрывозащиту.</p>\n  <figure>\n    <img src=\"content/groups/1eo-25/mdk-04-02/semester-1/light-sources-luminaires/images/explosion-proof-luminaires.png\" alt=\"Взрывозащищённые светильники для помещений с опасной средой\" />\n    <figcaption>Рисунок 5 — Взрывозащищённые светильники для помещений с опасной средой.</figcaption>\n  </figure>\n</section>\n\n<section>\n  <h2>Выводы</h2>\n  <ul>\n    <li>Источники света различаются по принципу действия, световой отдаче, сроку службы и требованиям к подключению.</li>\n    <li>Газоразрядные лампы экономичны, но требуют балласта и времени на разгорание.</li>\n    <li>Светодиодные светильники удобны и экономичны, но требуют качественного драйвера и охлаждения.</li>\n    <li>Арматура определяет безопасность, защиту от среды и распределение света.</li>\n    <li>Для промышленного освещения важно правильно выбрать вид освещения, степень защиты и исполнение светильника.</li>\n  </ul>\n</section>\n\n<section>\n  <h2>Вопросы для самопроверки</h2>\n  <ol>\n    <li>Чем тепловые источники света отличаются от газоразрядных?</li>\n    <li>Зачем газоразрядной лампе нужна пускорегулирующая аппаратура?</li>\n    <li>Какие преимущества и ограничения есть у светодиодных светильников?</li>\n    <li>Что входит в осветительную арматуру и какие функции она выполняет?</li>\n    <li>Чем рабочее освещение отличается от аварийного?</li>\n    <li>Почему в пыльном или взрывоопасном помещении нельзя применять обычный светильник?</li>\n  </ol>\n</section>\n\n<p><a href=\"content/groups/1eo-25/mdk-04-02/semester-1/light-sources-luminaires/docs/Лекция — Электрические источники света и осветительная арматура.docx\">Скачать лекцию в Word (.docx)</a></p>\n","electromagnetism-lecture":"  <p>Электромагнетизм изучает связь электрических токов и магнитных полей. Магнитное поле проявляется при движении зарядов, работе электрических машин, трансформаторов, реле и измерительных приборов. Понимание магнитных величин нужно для расчёта магнитных цепей и объяснения электромагнитной индукции.</p>\n<section>\n  <h2>Магнитное поле</h2>\n  <p>Магнитное поле — особый вид материи, через который передаётся действие магнитных сил на движущиеся электрические заряды и постоянные магниты. Оно возникает вокруг движущихся зарядов, проводников с током и постоянных магнитов.</p>\n  <p>Электрическое и магнитное поля неразрывны: изменяющееся электрическое поле порождает магнитное, а изменяющееся магнитное — электрическое. Электромагнитное поле распространяется со скоростью света — около 300 000 км/с.</p>\n  <p>Магнитное поле обнаруживают по действию на движущиеся заряженные частицы, проводник с током, постоянные магниты и ферромагнитные тела.</p>\n  <p>Для наглядности поле изображают магнитными силовыми линиями. Это замкнутые линии, показывающие направление поля. Вне магнита они направлены от северного полюса к южному, внутри замыкаются. Чем гуще линии, тем сильнее поле.</p>\n  <p>Направление магнитных линий определяют правилом буравчика: если ввинчивать буравчик по направлению тока, то направление вращения рукоятки совпадает с направлением магнитных линий.</p>\n  <figure>\n    <img src=\"content/groups/1a-25-3a-26-11/op-03/electromagnetism/images/fig-3-1-magnetic-field.png\" alt=\"Магнитное поле: а — прямого провода; б — подковообразного магнита\" />\n    <figcaption>Рисунок 1 — Магнитное поле: а — прямого провода; б — подковообразного магнита.</figcaption>\n  </figure>\n</section>\n<section>\n  <h2>Магнитная индукция и магнитный поток</h2>\n  <p>Магнитная индукция B — векторная величина, характеризующая интенсивность магнитного поля в данной точке. Вектор B направлен по касательной к магнитной силовой линии.</p>\n  <ul class=\"formulas\">\n    <li>1 Тл = 1 Н / (А · м)</li>\n  </ul>\n  <p>Направление силы, действующей на проводник с током в магнитном поле, определяют правилом левой руки: магнитные линии входят в ладонь, четыре вытянутых пальца направлены по току, а отогнутый большой палец показывает направление силы.</p>\n  <p>Магнитный поток Φ — величина, равная произведению магнитной индукции на площадь поверхности, перпендикулярной вектору B.</p>\n  <ul class=\"formulas\">\n    <li>Φ = B · S</li>\n  </ul>\n  <p>Единица магнитного потока — вебер:</p>\n  <ul class=\"formulas\">\n    <li>1 Вб = 1 Тл · м²</li>\n  </ul>\n  <p>Если магнитный поток через контур изменяется, в контуре возникает ЭДС электромагнитной индукции. Это явление лежит в основе работы генераторов, трансформаторов, электродвигателей и дросселей.</p>\n  <figure>\n    <img src=\"content/groups/1a-25-3a-26-11/op-03/electromagnetism/images/fig-3-2-field-wire-coil.png\" alt=\"Магнитное поле: а — прямого провода; б — индуктивной катушки\" />\n    <figcaption>Рисунок 2 — Магнитное поле: а — прямого провода; б — индуктивной катушки.</figcaption>\n  </figure>\n</section>\n<section>\n  <h2>МДС и напряжённость магнитного поля</h2>\n  <p>Источником магнитного поля в магнитной цепи является магнитодвижущая сила (МДС). Для катушки с числом витков w и током I:</p>\n  <ul class=\"formulas\">\n    <li>F<sub>мдс</sub> = I · w</li>\n  </ul>\n  <p>Единица МДС — ампер. Если магнитная линия охватывает несколько токов, МДС равна алгебраической сумме этих токов:</p>\n  <ul class=\"formulas\">\n    <li>F<sub>мдс</sub> = ΣI</li>\n  </ul>\n  <p>Напряжённость магнитного поля H — это МДС, приходящаяся на единицу длины магнитной линии:</p>\n  <ul class=\"formulas\">\n    <li>H = F<sub>мдс</sub> / l</li>\n  </ul>\n  <p>Единица напряжённости — ампер на метр. Для прямолинейного проводника с током напряжённость на расстоянии x от провода:</p>\n  <ul class=\"formulas\">\n    <li>H = I / (2πx)</li>\n  </ul>\n  <p>По мере удаления от проводника напряжённость поля уменьшается.</p>\n  <figure>\n    <img src=\"content/groups/1a-25-3a-26-11/op-03/electromagnetism/images/fig-3-3-left-hand-rule.png\" alt=\"Определение направления электромагнитной силы по правилу левой руки\" />\n    <figcaption>Рисунок 3 — Определение направления электромагнитной силы по правилу левой руки.</figcaption>\n  </figure>\n</section>\n<section>\n  <h2>Магнитная цепь</h2>\n  <p>Магнитная цепь — совокупность элементов, по которым замыкается магнитный поток. Обычно она включает ферромагнитный сердечник, воздушный зазор и катушку с током — источник МДС.</p>\n  <ul>\n    <li>МДС создаёт магнитный поток.</li>\n    <li>Сердечник направляет поток по нужному пути.</li>\n    <li>Воздушный зазор увеличивает магнитное сопротивление цепи.</li>\n  </ul>\n  <p>Магнитные цепи лежат в основе трансформаторов, электрических машин, реле, дросселей и электромагнитов.</p>\n  <figure>\n    <img src=\"content/groups/1a-25-3a-26-11/op-03/electromagnetism/images/fig-3-4-toroid.png\" alt=\"Тороидальная катушка\" />\n    <figcaption>Рисунок 4 — Тороидальная катушка.</figcaption>\n  </figure>\n</section>\n<section>\n  <h2>Магнитная проницаемость и кривые намагничивания</h2>\n  <p>Абсолютная магнитная проницаемость μ<sub>a</sub> показывает, во сколько раз индукция в данной среде отличается от индукции в вакууме при той же напряжённости:</p>\n  <ul class=\"formulas\">\n    <li>μ<sub>a</sub> = B / H</li>\n  </ul>\n  <p>Единица — генри на метр. Магнитная постоянная:</p>\n  <ul class=\"formulas\">\n    <li>μ<sub>0</sub> = 4π · 10⁻⁷ Гн/м</li>\n  </ul>\n  <p>Для воздуха и неферромагнитных материалов μ<sub>a</sub> примерно равна μ<sub>0</sub>. Относительная магнитная проницаемость μ показывает, во сколько раз μ<sub>a</sub> материала больше μ<sub>0</sub>:</p>\n  <ul class=\"formulas\">\n    <li>μ = μ<sub>a</sub> / μ<sub>0</sub></li>\n  </ul>\n  <p>У ферромагнитных материалов — железа, стали, пермаллоя — μ во много раз больше единицы. При этом μ зависит от напряжённости поля и степени намагничивания.</p>\n  <p>Зависимость B(H) для ферромагнетика нелинейна: сначала индукция быстро растёт, затем рост замедляется — наступает магнитное насыщение. Поэтому при расчётах μ берут по кривой намагничивания для конкретного материала и режима.</p>\n  <figure>\n    <img src=\"content/groups/1a-25-3a-26-11/op-03/electromagnetism/images/fig-3-5-magnetization-curves.png\" alt=\"Семейство кривых намагничивания: 1 — технически чистое железо; 2 — электротехническая сталь; 3 — пермаллой\" />\n    <figcaption>Рисунок 5 — Семейство кривых намагничивания: 1 — технически чистое железо; 2 — электротехническая сталь; 3 — пермаллой.</figcaption>\n  </figure>\n</section>\n<section>\n  <h2>Примеры расчёта</h2>\n  <p>Пример 3.1. Сталь обладает абсолютной магнитной проницаемостью μ<sub>a</sub> = 0,0008792 Гн/м. Определить относительную магнитную проницаемость.</p>\n  <ul class=\"formulas\">\n    <li>μ = 0,0008792 / (4 · 3,14 · 10⁻⁷) ≈ 700</li>\n  </ul>\n  <p>Сталь — ферромагнитный материал, поэтому μ значительно больше единицы.</p>\n  <p>Пример 3.2. Напряжённость магнитного поля в сердечнике H = 750 А/м, абсолютная проницаемость μ<sub>a</sub> = 0,0008792 Гн/м. Определить магнитную индукцию.</p>\n  <ul class=\"formulas\">\n    <li>B = μ<sub>a</sub> · H = 0,0008792 · 750 = 0,6594 Тл</li>\n  </ul>\n  <p>Приближённо B ≈ 0,66 Тл.</p>\n</section>\n<section>\n  <h2>Выводы</h2>\n  <ul>\n    <li>Магнитное поле — особая форма материи, действующая на движущиеся заряды и магниты.</li>\n    <li>Магнитные силовые линии замкнуты; их направление определяют правилом буравчика.</li>\n    <li>Основные величины: магнитная индукция B, магнитный поток Φ, МДС F<sub>мдс</sub>, напряжённость H.</li>\n    <li>Магнитная проницаемость ферромагнетиков нелинейна; её определяют по кривой намагничивания.</li>\n    <li>Магнитная цепь направляет поток; воздушный зазор сильно увеличивает требуемую МДС.</li>\n    <li>Изменение магнитного потока вызывает ЭДС электромагнитной индукции.</li>\n  </ul>\n</section>\n<section>\n  <h2>Контрольные вопросы</h2>\n  <ol>\n    <li>Что такое магнитное поле и как его обнаруживают?</li>\n    <li>Какими свойствами обладают магнитные силовые линии?</li>\n    <li>Сформулируйте правило буравчика и правило левой руки.</li>\n    <li>Дайте определения магнитной индукции, магнитного потока, МДС и напряжённости поля. Назовите единицы.</li>\n    <li>Чем абсолютная магнитная проницаемость отличается от относительной?</li>\n    <li>Почему кривая B(H) ферромагнетика имеет участок насыщения?</li>\n    <li>Из каких элементов состоит простейшая магнитная цепь и зачем нужен сердечник?</li>\n    <li>Как изменение магнитного потока связано с электромагнитной индукцией?</li>\n  </ol>\n</section>\n<p><a href=\"content/groups/1a-25-3a-26-11/op-03/electromagnetism/docs/Лекция — Электромагнетизм и электромагнитная индукция.docx\">Скачать лекцию в Word (.docx)</a></p>\n","lighting-network-check-practice":"<section>\n<p>Цель работы — проверить осветительную группу по нагреву и потере напряжения, выбрать сечение кабеля и аппарат защиты, построить расчётную схему и график распределения напряжения вдоль линии.</p>\n</section>\n<section>\n<h2>1. Исходные данные</h2>\n<p>Для расчёта принят вариант 1: группа из 20 светильников мощностью 100 Вт каждый, установленных с шагом 5 м. Расстояние от щита до первого светильника — 5 м, до последнего — 100 м. Напряжение сети 230 В, материал кабеля — медь, удельная проводимость γ = 57 м/(Ом·мм²).</p>\n<p class=\"table-hint table-hint-mobile\">Прокрутите таблицу вправо →</p><div class=\"table-scroll\"><table class=\"practice-table\"><thead><tr><th>Вариант</th><th>Число светильников</th><th>P_л, Вт</th><th>Шаг, м</th><th>L, м</th><th>ΔU_доп, %</th></tr></thead><tbody><tr><td>1</td><td>20</td><td>100</td><td>5</td><td>100</td><td>2,5</td></tr><tr><td>2</td><td>16</td><td>100</td><td>5</td><td>80</td><td>2,5</td></tr><tr><td>3</td><td>12</td><td>150</td><td>6</td><td>72</td><td>3,0</td></tr><tr><td>4</td><td>24</td><td>60</td><td>4</td><td>96</td><td>2,5</td></tr></tbody></table></div>\n<p class=\"table-caption\">Таблица 1 — Варианты исходных данных</p>\n<p>Расчёт выполнен для варианта 1. Проверяются четыре возможных сечения жил: 1,5; 2,5; 4 и 6 мм². Автомат предварительно принимается по расчётному току.</p>\n</section>\n<section>\n<h2>2. Расчётная схема</h2>\n<figure class=\"wide-figure\"><a href=\"content/groups/1me-25/mdk-05-02/lighting-network-check/images/scheme.png\" target=\"_blank\" rel=\"noopener\"><img src=\"content/groups/1me-25/mdk-05-02/lighting-network-check/images/scheme.png\" alt=\"Рисунок 1 — Расчётная схема осветительной сети\" loading=\"lazy\" /></a><figcaption>Рисунок 1 — Расчётная схема осветительной сети</figcaption></figure>\n<p>На схеме показаны щит с напряжением 230 В, автоматический выключатель QF1, кабельная линия и 20 светильников. Расстояние между соседними светильниками равно 5 м, расстояние от щита до последнего светильника — 100 м. Именно последний светильник будет иметь наименьшее напряжение, поэтому его режим является проверочным.</p>\n</section>\n<section>\n<h2>3. Проверка по нагреву</h2>\n<p>Суммарная мощность группы:</p>\n<p class=\"formula\">PΣ = n · Pл = 20 · 100 = 2000 Вт</p>\n<p>Расчётный ток при cos φ = 1:</p>\n<p class=\"formula\">Iр = PΣ / (Uн · cos φ) = 2000 / 230 = 8,70 А</p>\n<p>Принимаем QF1 на 10 А. <strong>Длительно допустимые токи медного кабеля: 19; 25; 30 и 40 А для сечений 1,5; 2,5; 4 и 6 мм²</strong>. Все варианты проходят по нагреву: 8,70 А меньше каждого из этих токов. </p>\n</section>\n<section>\n<h2>4. Расчёт потери напряжения</h2>\n<p>При равномерной нагрузке вдоль линии суммарный момент нагрузки определяется по формуле:</p>\n<p class=\"formula\">M = Pл · Δl · n · (n + 1) / 2</p>\n<p>Для варианта 1:</p>\n<p class=\"formula\">M = 100 · 5 · 20 · 21 / 2 = 105 000 Вт·м</p>\n<p>Потеря напряжения в двухпроводной линии:</p>\n<p class=\"formula\">ΔU = 2 · M / (γ · S · Uн)</p>\n<p>Потеря напряжения в процентах и напряжение у последнего светильника:</p>\n<p class=\"formula\">ΔU% = 100 · ΔU / Uн</p>\n<p class=\"formula\">Uл = Uн − ΔU</p>\n<p>Допустимое напряжение при ΔU_доп = 2,5 %:</p>\n<p class=\"formula\">Uдоп = 230 · (1 − 0,025) = 224,25 В</p>\n<p>Для сечения 1,5 мм²:</p>\n<p class=\"formula\">ΔU = 2 · 105 000 / (57 · 1,5 · 230) = 10,68 В</p>\n<p class=\"formula\">ΔU% = 100 · 10,68 / 230 = 4,64 %</p>\n<p class=\"formula\">Uл = 230 − 10,68 = 219,32 В</p>\n<p>Напряжение ниже 224,25 В, условие не выполняется.</p>\n<p>Для сечения 2,5 мм²:</p>\n<p class=\"formula\">ΔU = 2 · 105 000 / (57 · 2,5 · 230) = 6,41 В</p>\n<p class=\"formula\">ΔU% = 100 · 6,41 / 230 = 2,79 %</p>\n<p class=\"formula\">Uл = 230 − 6,41 = 223,59 В</p>\n<p>Напряжение ниже допустимого на 0,66 В, условие не выполняется.</p>\n<p>Для сечения 4 мм²:</p>\n<p class=\"formula\">ΔU = 2 · 105 000 / (57 · 4 · 230) = 4,00 В</p>\n<p class=\"formula\">ΔU% = 100 · 4,00 / 230 = 1,74 %</p>\n<p class=\"formula\">Uл = 230 − 4,00 = 226,00 В</p>\n<p>Напряжение выше 224,25 В, условие выполняется.</p>\n<p>Для сечения 6 мм²:</p>\n<p class=\"formula\">ΔU = 2 · 105 000 / (57 · 6 · 230) = 2,67 В</p>\n<p class=\"formula\">ΔU% = 100 · 2,67 / 230 = 1,16 %</p>\n<p class=\"formula\">Uл = 230 − 2,67 = 227,33 В</p>\n<p>Условие выполняется с запасом, но сечение 6 мм² экономически нецелесообразно.</p>\n<p class=\"table-hint table-hint-mobile\">Прокрутите таблицу вправо →</p><div class=\"table-scroll\"><table class=\"practice-table\"><thead><tr><th>S, мм²</th><th>ΔU, В</th><th>ΔU, %</th><th>U_л, В</th><th>Проверка</th></tr></thead><tbody><tr><td>1,5</td><td>10,68</td><td>4,64</td><td>219,32</td><td>не проходит</td></tr><tr><td>2,5</td><td>6,41</td><td>2,79</td><td>223,59</td><td>не проходит</td></tr><tr><td>4,0</td><td>4,00</td><td>1,74</td><td>226,00</td><td>проходит</td></tr><tr><td>6,0</td><td>2,67</td><td>1,16</td><td>227,33</td><td>проходит</td></tr></tbody></table></div>\n<p class=\"table-caption\">Таблица 2 — Результаты проверки по потере напряжения</p>\n<p>Минимальное сечение, при котором напряжение у последнего светильника не ниже 224,25 В, — 4 мм². Сечение 2,5 мм² проходит по нагреву, но не проходит по потере напряжения, поэтому его принимать нельзя.</p>\n</section>\n<section>\n<h2>5. График напряжения вдоль линии</h2>\n<p>Для наглядности построен график напряжения у каждого светильника. Расчёт для k-го светильника ведётся по накопленному моменту нагрузки:</p>\n<p class=\"formula\">Mk = Pл · Δl · k · (k + 1) / 2</p>\n<p class=\"formula\">Uk = Uн − 2 · Mk / (γ · S · Uн)</p>\n<figure class=\"wide-figure\"><a href=\"content/groups/1me-25/mdk-05-02/lighting-network-check/images/voltage-graph.png\" target=\"_blank\" rel=\"noopener\"><img src=\"content/groups/1me-25/mdk-05-02/lighting-network-check/images/voltage-graph.png\" alt=\"Рисунок 2 — Напряжение у светильников вдоль линии\" loading=\"lazy\" /></a><figcaption>Рисунок 2 — Напряжение у светильников вдоль линии</figcaption></figure>\n<p>Кривая для сечения 1,5 мм² пересекает допустимый уровень примерно у 15-го светильника и к концу линии снижается до 219,3 В. Кривая 2,5 мм² подходит к границе вплотную и у последнего светильника даёт 223,6 В, то есть не проходит. Кривые 4 и 6 мм² остаются выше линии 224,25 В на всём участке. Для дальнейшего расчёта принимаем 4 мм²: это минимальное сечение, которое обеспечивает норму с небольшим запасом.</p>\n</section>\n<section>\n<h2>6. Вывод</h2>\n<p>Для осветительной группы из 20 светильников по 100 Вт с шагом 5 м и общей длиной линии 100 м принимаем:</p>\n<ul>\n<li>автоматический выключатель QF1 — 10 А;</li>\n<li>кабель с медными жилами сечением 4 мм²;</li>\n<li>расчётная потеря напряжения — 1,74 %;</li>\n<li>напряжение у последнего светильника — 226,0 В, что выше допустимых 224,25 В;</li>\n<li>кабель проходит по нагреву: 8,70 А &lt; 30 А.</li>\n</ul>\n<p>Сечение 1,5 мм² не проходит по потере напряжения, 2,5 мм² — тоже не проходит, хотя оба варианта проходят по нагреву. Это показывает, что проверка только по нагреву недостаточна. Если разделить группу на две линии по 10 светильников, можно использовать кабель 2,5 мм², но потребуется второй автомат и больше кабеля; в данном решении принят один кабель 4 мм².</p>\n</section>\n<p><a href=\"content/groups/1me-25/mdk-05-02/lighting-network-check/docs/Практическая работа — Проверка осветительной сети.docx\">Скачать практическую работу в Word (.docx)</a></p>\n","three-phase-meter-connection-practice":"<section>\n<p><strong>Цель работы: </strong>изучить схему прямого включения трёхфазного счётчика, порядок монтажа, наладки и проверки; научиться выбирать счётчик, вводный автомат и кабель по допустимым токам.</p>\n<p><strong>Исходные данные. </strong>Трёхфазная сеть 3×230/400 В, 50 Гц; cos φ — по варианту; включение счётчика — прямое, 0,4 кВ; мощность нагрузки P — по варианту.</p>\n</section>\n<section>\n<h2>Варианты исходных данных</h2>\n<div class=\"table-scroll\"><table class=\"practice-table variants-table practice-table-fit\"><thead><tr><th>Вар.</th><th>Мощность P, кВт</th><th>cos φ</th><th>U, В</th><th>Iр, А (по формуле)</th></tr></thead><tbody><tr><td>1</td><td>10</td><td>0,92</td><td>400</td><td>—</td></tr><tr><td>2</td><td>20</td><td>0,88</td><td>400</td><td>—</td></tr><tr><td>3</td><td>30</td><td>0,84</td><td>400</td><td>—</td></tr><tr><td>4</td><td>40</td><td>0,80</td><td>400</td><td>—</td></tr></tbody></table></div>\n<p><strong>1. Формулы для расчёта. </strong>Расчётный ток линии и условия выбора:</p>\n<p class=\"formula\">Iр = P / (√3 · U · cos φ)</p>\n<p class=\"formula\">Iр ≤ Iмакс</p>\n<p class=\"formula\">Iр ≤ Iном ≤ Iдоп</p>\n<p>Счётчик выбирают по максимальному току, вводный автомат — по номинальному току, кабель — по длительно допустимому току. <strong>Числовые расчёты в работе не выполняются.</strong></p>\n<div class=\"table-pair\"><div><h3>Счётчики</h3><div class=\"table-scroll\"><table class=\"practice-table practice-table-fit\"><thead><tr><th>Тип счётчика</th><th>Iмакс, А</th></tr></thead><tbody><tr><td>Энергомера CE 102</td><td>60</td></tr><tr><td>Энергомера CE 208</td><td>60</td></tr><tr><td>Меркурий 234</td><td>60</td></tr><tr><td>Энергомера CE 102</td><td>100</td></tr><tr><td>Энергомера CE 308</td><td>100</td></tr><tr><td>Меркурий 234</td><td>100</td></tr></tbody></table></div></div><div><h3>Вводные автоматы и кабели</h3><div class=\"table-scroll\"><table class=\"practice-table practice-table-fit\"><thead><tr><th>QF Iном, А</th><th>Iдоп, А</th><th>S, мм²</th></tr></thead><tbody><tr><td>20</td><td>25</td><td>4</td></tr><tr><td>32</td><td>40</td><td>6</td></tr><tr><td>40</td><td>50</td><td>10</td></tr><tr><td>63</td><td>70</td><td>16</td></tr><tr><td>80</td><td>100</td><td>25</td></tr><tr><td>100</td><td>135</td><td>35</td></tr></tbody></table></div></div></div>\n<figure class=\"wide-figure\"><a href=\"content/groups/1eo-24/mdk-04-02/semester-3/three-phase-meter-connection/images/meter-connection.png\" target=\"_blank\" rel=\"noopener\"><img src=\"content/groups/1eo-24/mdk-04-02/semester-3/three-phase-meter-connection/images/meter-connection.png\" alt=\"Рисунок 1 — Схема прямого включения трёхфазного счётчика\" loading=\"lazy\" /></a><figcaption>Рисунок 1 — Схема прямого включения трёхфазного счётчика</figcaption></figure>\n<p><strong>Клеммы счётчика: </strong>1–2 — L1; 3–4 — L2; 5–6 — L3; 7–8 — N. PE-проводник проходит отдельно, к шине PE, минуя счётчик.</p>\n<p><strong>2. Монтаж. </strong></p>\n<ul>\n<li>Отключить линию, заблокировать QF1, проверить отсутствие напряжения; установить счётчик на DIN-рейку.</li>\n<li>Завести кабель: вход — 1, 3, 5, 7; выход — 2, 4, 6, 8. PE подключить отдельно.</li>\n<li>Затянуть клеммы, проверить маркировку, отсутствие замыканий и надёжность контактов.</li>\n<li>Подать напряжение, проверить наличие фаз, дисплей и отсутствие обратного отсчёта.</li>\n</ul>\n<p><strong>3. Наладка. </strong>Проверить порядок фаз L1–L2–L3, напряжение на входе и выходе, отсутствие отсчёта без нагрузки, работу счётчика под нагрузкой; установить дату, время и тариф; опломбировать клеммную крышку.</p>\n<p><strong>4. Ремонт и типовые неисправности. </strong></p>\n<p>Нет индикации — проверить питание и контакты; </p>\n<p>обратный отсчёт — проверить направление включения; </p>\n<p>нагрев клемм — проверить затяжку и сечение. </p>\n<p>Внутренний ремонт счётчика выполняет специализированная организация, в мастерской счётчик заменяют.</p>\n<p><strong>5. Охрана труда. </strong>Работы выполняет электромонтёр не ниже III группы: отключение, проверка отсутствия напряжения, диэлектрические СИЗ и изолированный инструмент.</p>\n<p><strong>Вывод. </strong>Счётчик выбирают по Iмакс, автомат — по Iном, кабель — по Iдоп; правильность выбора проверяют по формулам Iр ≤ Iном.макс и Iр ≤ Iном ≤ Iдоп.</p>\n</section>\n<p><a href=\"content/groups/1eo-24/mdk-04-02/semester-3/three-phase-meter-connection/docs/Расчётно-практическая работа — Трёхфазный счётчик.docx\">Скачать работу в Word (.docx)</a></p>\n","lighting-installation-repair-lecture":"<section>\n<p>Светильники общего применения служат для освещения жилых, офисных, торговых, учебных и производственных помещений. От правильного выбора, крепления и подключения зависят безопасность, долговечность и качество освещения.</p>\n</section>\n<section>\n<h2>1. Назначение и классификация</h2>\n<p>Светильник — осветительный прибор, объединяющий источник света, арматуру, устройства крепления и подключения. Светильники различают по назначению, способу установки, источнику света, степени защиты и классу защиты от поражения током.</p>\n<ul>\n<li>По назначению: общего, местного, рабочего, аварийного, эвакуационного и охранного освещения.</li>\n<li>По установке: потолочные, подвесные, настенные, встраиваемые, консольные и трековые.</li>\n<li>По источнику света: лампы накаливания, галогенные, люминесцентные и светодиодные.</li>\n<li>По степени защиты: от IP20 для сухих помещений до IP65 для пыльных и влажных.</li>\n<li>По классу защиты от поражения током: 0, I, II, III; по исполнению — обычное, пылевлагозащищённое, взрывозащищённое.</li>\n</ul>\n<p>Для общего применения чаще используют светильники IP20–IP54 со светодиодными модулями или люминесцентными лампами. Во влажных помещениях применяют исполнение не ниже IP44, в пыльных — IP54/IP65.</p>\n</section>\n<section>\n<h2>2. Устройство и маркировка</h2>\n<p>Основные элементы светильника: корпус, отражатель или рассеиватель, патрон или LED-модуль, драйвер или пускорегулирующий аппарат, клеммная колодка, устройство крепления, клемма заземления, уплотнения и кабельные вводы.</p>\n<p>Маркировка содержит тип, мощность, напряжение, тип источника света, степень защиты IP, класс защиты от поражения током, цветовую температуру и производителя. Пример: LED 40 Вт · 230 В · IP20 · 4000 К · класс II.</p>\n<p>Перед монтажом проверяют соответствие светильника условиям среды, допустимую мощность и тип лампы, наличие клеммы PE, целостность корпуса, рассеивателя и уплотнений, соответствие напряжения сети.</p>\n<figure class=\"wide-figure\"><a href=\"content/groups/1eo-25/mdk-04-02/semester-1/lighting-installation-repair/images/ceiling-luminaire.png\" target=\"_blank\" rel=\"noopener\"><img src=\"content/groups/1eo-25/mdk-04-02/semester-1/lighting-installation-repair/images/ceiling-luminaire.png\" alt=\"Рисунок 1 — Устройство точечного светильника для натяжного потолка: 1 — потолок; 2 — LED-лампа MR-16; 3 — универсальная платформа; 4 — регулируемая стойка; 5 — патрон GU 5,3; 6 — натяжной потолок; 7 — проводка в гофре; 8 — бетонный потолок; 9 — термокольцо; 10 — светильник\" loading=\"lazy\" /></a><figcaption>Рисунок 1 — Устройство точечного светильника для натяжного потолка: 1 — потолок; 2 — LED-лампа MR-16; 3 — универсальная платформа; 4 — регулируемая стойка; 5 — патрон GU 5,3; 6 — натяжной потолок; 7 — проводка в гофре; 8 — бетонный потолок; 9 — термокольцо; 10 — светильник</figcaption></figure>\n</section>\n<section>\n<h2>3. Подготовка и способы крепления</h2>\n<p>Перед монтажом светильники осматривают, маркируют фазные и нулевые провода, выполняют зарядку: присоединяют внутренние провода к патрону и устанавливают источник света. Люминесцентные светильники при необходимости собирают в блоки и комплектные линии.</p>\n<p>Монтаж включает установку деталей крепления, подвешивание или крепление светильника, присоединение к электросети и сети заземления. Применяют крюки и шпильки, кронштейны, тросовые подвесы, монтажные шины, короба и переходные платформы.</p>\n<p>Светильники массой до 10 кг допускается подвешивать на крюках с кольцами или скобами. Крюки и подвесы для светильников массой до 100 кг испытывают пятикратной массой, свыше 100 кг — двукратной массой плюс 80 кг. Крепление на дюбелях проверяют тройной массой светильника плюс 80 кг.</p>\n<p>Внутренние провода светильника — медные, сечением 0,5–1,5 мм². Соединять провода внутри подвесов, кронштейнов и штанг запрещено. Металлические корпуса присоединяют к PE отдельным защитным проводником.</p>\n<figure class=\"small-figure\"><a href=\"content/groups/1eo-25/mdk-04-02/semester-1/lighting-installation-repair/images/mounting-methods.png\" target=\"_blank\" rel=\"noopener\"><img src=\"content/groups/1eo-25/mdk-04-02/semester-1/lighting-installation-repair/images/mounting-methods.png\" alt=\"Рисунок 2 — Способы крепления светильников к строительным конструкциям\" loading=\"lazy\" /></a><figcaption>Рисунок 2 — Способы крепления светильников к строительным конструкциям</figcaption></figure>\n</section>\n<section>\n<h2>4. Монтаж в разные типы потолков</h2>\n<p>В бетонном потолке используют крюк с дюбелем, крепёжную скобу или монтажную платформу. Для тяжёлой люстры крепление выполняют к плите перекрытия, а не к декоративной отделке. В тонком потолке применяют крюки с поворотными упорами или удлинённые болты с упорными шайбами.</p>\n<p>В деревянном потолке крюк вворачивают в несущую балку; лёгкие светильники крепят шурупами длиной 25–35 мм. В гипсокартон проводку прокладывают до монтажа подвесного потолка, затем сверлят отверстия, выводят провода, подключают патрон, сжимают пружины и вводят светильник в отверстие.</p>\n<p>В натяжной потолок светильник крепят к базовому бетонному потолку через регулируемую платформу. Платформу выставляют так, чтобы светильник был ниже полотна на 60–70 мм. В месте установки приклеивают прозрачное протекторное термокольцо, внутри него надрезают полотно, выводят провода, подключают патрон и фиксируют светильник пружинными защёлками. Тяжёлые люстры подвешивают к основному перекрытию через переходную конструкцию: декоративный потолок не должен воспринимать их вес.</p>\n</section>\n<section>\n<h2>5. Схема трёхфазной групповой линии</h2>\n<p>Ввод выполняется пятипроводной линией 3×230/400 В: L1, L2, L3, N, PE. Светильники распределяют по фазам равномерно. Выключатели устанавливают только в фазном проводе; N и PE не коммутируют. Корпуса металлических светильников обязательно заземляют.</p>\n</section>\n<section>\n<h2>6. Технология монтажа</h2>\n<ol>\n<li>Подготовка: проверить светильники, крепёж и инструмент; отключить линию, заблокировать автомат, проверить отсутствие напряжения.</li>\n<li>Разметка: определить высоту, оси светильников и места крепления; проверить отсутствие скрытой проводки.</li>\n<li>Крепление: установить крюк, кронштейн, платформу или монтажную шину; крепёж должен соответствовать массе светильника и материалу основания.</li>\n<li>Подключение: завести кабель через ввод, подключить L, N, PE по маркировке клемм; соединения выполнять клеммами, а не скрутками.</li>\n<li>Проверка: проверить затяжку клемм, изоляцию, отсутствие замыканий, надёжность крепления и заземления.</li>\n<li>Включение: подать напряжение, проверить выключатель, отсутствие мерцания и нагрева, работу светильника.</li>\n</ol>\n<p>При монтаже недопустимо подключать PE к рабочему нулю, коммутировать N выключателем, оставлять оголённые жилы, применять крепёж меньше требуемого по массе и ставить светильник с меньшим IP, чем требует помещение.</p>\n</section>\n<section>\n<h2>7. Ремонт и типовые неисправности</h2>\n<div class=\"table-scroll\"><table class=\"practice-table practice-table-fit\"><thead><tr><th>Неисправность</th><th>Вероятная причина</th><th>Действие</th></tr></thead><tbody><tr><td>Не включается</td><td>Нет напряжения, неисправен выключатель, плохой контакт</td><td>Проверить питание, выключатель, клеммы</td></tr><tr><td>Мерцает</td><td>Плохой контакт, драйвер, лампа</td><td>Протянуть клеммы, заменить драйвер или лампу</td></tr><tr><td>Светит частично</td><td>Обрыв LED-модуля, повреждение платы</td><td>Заменить модуль или светильник</td></tr><tr><td>Нагревается</td><td>Несоответствие мощности, плохой теплоотвод</td><td>Проверить режим и вентиляцию</td></tr><tr><td>Срабатывает защита</td><td>Замыкание, повреждение изоляции, влага</td><td>Отключить, проверить изоляцию и вводы</td></tr></tbody></table></div>\n<p>Ремонт начинают с отключения линии и проверки отсутствия напряжения. Сначала проверяют внешние цепи, клеммы, выключатель и источник света. Герметичные LED-светильники и драйверы обычно не ремонтируют, а заменяют.</p>\n</section>\n<section>\n<h2>8. Охрана труда</h2>\n<p>Работы выполняет электромонтёр не ниже III группы. Обязательны отключение и блокировка автомата, проверка отсутствия напряжения, диэлектрические СИЗ и изолированный инструмент, устойчивые лестницы, стремянки или подмости, защита глаз при работе с рассеивателями и лампами. Запрещается работать под напряжением, оставлять открытые токоведущие части и применять неисправный инструмент.</p>\n</section>\n<section>\n<h2>9. Контрольные вопросы</h2>\n<ol>\n<li>Чем светильник отличается от источника света?</li>\n<li>Что означает маркировка IP20, IP44 и IP65?</li>\n<li>Почему PE-проводник нельзя подключать к рабочему нулю?</li>\n<li>Как проверить надёжность крепления светильника?</li>\n<li>Почему нельзя соединять провода внутри подвеса или кронштейна?</li>\n<li>Как найти причину мерцания светильника?</li>\n<li>Какие меры безопасности соблюдают при монтаже на высоте?</li>\n</ol>\n</section>\n<section>\n<h2>Практическое задание</h2>\n<ul>\n<li>Выбрать светильник для помещения с заданными условиями, обосновать степень защиты IP и класс защиты от поражения током.</li>\n<li>Составить схему групповой линии, указать L, N, PE, способ крепления и порядок проверки перед включением.</li>\n</ul>\n</section>\n<section>\n<h2>Вывод</h2>\n<p>Светильник выбирают по назначению помещения, степени защиты, источнику света и классу защиты от поражения током. Монтаж включает подготовку, разметку, крепление, подключение L, N, PE и проверку. Для разных потолков применяют разные крепёжные системы; ремонт начинают с внешних цепей и заканчивают проверкой изоляции, заземления и работы светильника.</p>\n</section>\n<p><a href=\"content/groups/1eo-25/mdk-04-02/semester-1/lighting-installation-repair/docs/Лекция — Технология монтажа и ремонта светильников общего применения.docx\">Скачать лекцию в Word (.docx)</a></p>\n"};
